#include <fstream>
#include <memory>
#include <string>
#include <iostream>

struct Node {
    unsigned char character;
    int frequency;
    std::shared_ptr<Node> left;
    std::shared_ptr<Node> right;
    Node(unsigned char ch, int freq) : character(ch), frequency(freq), left(nullptr), right(nullptr) {}
};

std::string decode_data(std::ifstream &infile, std::shared_ptr<Node> &root, int encoded_length) {
    std::string decoded;
    if (!root) return decoded;
    std::shared_ptr<Node> current = root;
    int bits_read = 0;
    while (bits_read < encoded_length) {
        char byte;
        if (!infile.get(byte)) break;
        for (int i = 0; i < 8 && bits_read < encoded_length; ++i) {
            bool bit = (static_cast<unsigned char>(byte) >> (7 - i)) & 1U;
            if (bit) {
                if (current->right) current = current->right;
            } else {
                if (current->left) current = current->left;
            }
            if (!current->left && !current->right) {
                decoded.push_back(static_cast<char>(current->character));
                current = root;
            }
            ++bits_read;
        }
    }
    return decoded;
}

